function worldRecord(s,name){name=resolveObjectName(s,name);const entity=entityRecords(s).find(b=>b.name===name);if(entity)return entity;const moon=moonRecords(s).find(b=>b.name===name);if(moon)return moon;const star=starRecords(s).find(b=>b.name===name);if(star)return star;const station=stationRecords(s).find(b=>b.name===name);if(station)return station;if(!name||!s.worlds.includes(name))return null;return DATA.worlds[name]||{tag:siteType(name)==='World'?'Charted world':'Charted site',description:`${name} is named on the ${DATA.regions[s.region]?.name||'Codex'} chart${s.region?' in the '+s.name+' system':''}. Further physical and orbital details are not specified in the records used for this atlas.`,source:name,links:[]};}
